const query = $input.item.json.query;

// Get email and token from URL
const email    = (query.email || '').toLowerCase().trim();
const token    = (query.token || '').trim();

// Must have both
if (!email || !token) {
  throw new Error('Missing email or token');
}

// ── Recreate token using same function ────────────────
const secretKey = 'LeadMgmt2026@Secure'; // same key as Build Follow-up Email

function generateToken(email, secret) {
  const combined = email + secret + email.length;
  let hash = 0;
  for (let i = 0; i < combined.length; i++) {
    const char = combined.charCodeAt(i);
    hash = ((hash << 5) - hash) + char;
    hash = hash & hash;
  }
  const positiveHash = Math.abs(hash).toString(16);
  const extra = (email.length * secret.length).toString(16);
  return (positiveHash + extra + positiveHash)
    .padEnd(32, '0')
    .substring(0, 32);
}

const expectedToken = generateToken(email, secretKey);

// ── Compare tokens ────────────────────────────────────
const isValid = token === expectedToken;

return [{
  json: {
    email:      email,
    token:      token,
    is_valid:   isValid,
    verified_at: new Date().toLocaleString('en-IN', {
      timeZone: 'Asia/Kolkata'
    })
  }
}];

